function offsetPolygon(poly,d){
  return poly.map((p,i)=>{
    const a=poly[(i+poly.length-1)%poly.length],c=poly[(i+1)%poly.length];
    const u=[p[0]-a[0],p[1]-a[1]],v=[c[0]-p[0],c[1]-p[1]];
    const lu=Math.hypot(...u),lv=Math.hypot(...v);
    const n=[-u[1]/lu,u[0]/lu],m=[-v[1]/lv,v[0]/lv];
    const q=[p[0]+n[0]*d,p[1]+n[1]*d],r=[p[0]+m[0]*d,p[1]+m[1]*d];
    const den=u[0]*v[1]-u[1]*v[0];
    if(Math.abs(den)<1e-8)return q;
    const t=((r[0]-q[0])*v[1]-(r[1]-q[1])*v[0])/den;
    return [q[0]+u[0]*t,q[1]+u[1]*t];
  });
}
function geometryBuilder(){
  const pos=[];
  const tri=(a,b,c)=>pos.push(...a,...b,...c);
  const quad=(a,b,c,d)=>{tri(a,b,c);tri(a,c,d);};
  const finish=()=>{const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.computeVertexNormals();return g;};
  return {tri,quad,finish};
}
function plate(poly,depth,bevel=0.004){
  const b=Math.min(bevel,depth*0.32),small=offsetPolygon(poly,b),g=geometryBuilder();
  const loops=[small,poly,poly,small].map((p,i)=>p.map(q=>[q[0],q[1],[-depth/2,-depth/2+b,depth/2-b,depth/2][i]]));
  for(let k=0;k<3;k++)for(let i=0;i<poly.length;i++){const j=(i+1)%poly.length;g.quad(loops[k][i],loops[k][j],loops[k+1][j],loops[k+1][i]);}
  const cap=THREE.ShapeUtils.triangulateShape(small.map(p=>new THREE.Vector2(...p)),[]);
  for(const [a,b,c] of cap){g.tri(loops[0][c],loops[0][b],loops[0][a]);g.tri(loops[3][a],loops[3][b],loops[3][c]);}
  return g.finish();
}
function frame(outer,inner,depth,b=0.008){
  const g=geometryBuilder(),n=outer.length;
  const os=offsetPolygon(outer,b),is=offsetPolygon(inner,-b);
  const zs=[-depth/2,-depth/2+b,depth/2-b,depth/2];
  const O=[os,outer,outer,os].map((p,k)=>p.map(q=>[...q,zs[k]]));
  const I=[is,inner,inner,is].map((p,k)=>p.map(q=>[...q,zs[k]]));
  for(let k=0;k<3;k++)for(let i=0;i<n;i++){const j=(i+1)%n;g.quad(O[k][i],O[k][j],O[k+1][j],O[k+1][i]);g.quad(I[k][j],I[k][i],I[k+1][i],I[k+1][j]);}
  for(let i=0;i<n;i++){const j=(i+1)%n;g.quad(O[3][i],O[3][j],I[3][j],I[3][i]);g.quad(O[0][j],O[0][i],I[0][i],I[0][j]);}
  return g.finish();
}
function oct(w,h,c=0.035){return [[-w/2+c,-h/2],[w/2-c,-h/2],[w/2,-h/2+c],[w/2,h/2-c],[w/2-c,h/2],[-w/2+c,h/2],[-w/2,h/2-c],[-w/2,-h/2+c]];}

function group(parent,name,pos=[0,0,0],rot=[0,0,0]){const g=new THREE.Group();g.name=name;g.position.set(...pos);g.rotation.set(...rot.map(a=>a*Math.PI/180));parent.add(g);return g;}
function part(parent,name,geo,mat,pos=[0,0,0],rot=[0,0,0]){const p=createPart(name,geo,mat,{parent,position:pos,rotation:rot});p.name=name;return p;}
async function block(parent,name,s,pos,mat,r=0.06){return part(parent,name,await roundedBoxGeo(...s,Math.min(r,Math.min(...s)*0.3),{style:'chamfer'}),mat,pos);}
function panel(parent,name,w,h,d,c,pos,mat,rot=[0,0,0]){return part(parent,name,plate(oct(w,h,c),d,Math.min(d*0.25,0.025)),mat,pos,rot);}
function ring(parent,name,w,h,c,t,d,pos,mat,rot=[0,0,0]){return part(parent,name,frame(oct(w,h,c),oct(w-2*t,h-2*t,Math.max(0.025,c-t*0.6)),d,Math.min(t*0.12,d*0.18)),mat,pos,rot);}
function cyl(parent,name,r,d,pos,mat,rot=[0,0,0]){return part(parent,name,cylinderGeo(r,r,d,12),mat,pos,rot);}
function materialVariant(mat,name,i){const m=mat.clone();m.name=name;m.roughness+=i*0.002;return m;}
function beacon(parent,name,pos,m,s=1){const b=group(parent,name,pos);cyl(b,name+'_foot',0.11*s,0.07*s,[0,0.035*s,0],m.panelGray);part(b,name+'_case',plate(oct(0.19*s,0.23*s,0.025*s),0.18*s,0.014*s),m.panelGray,[0,0.18*s,0]);for(const side of [-1,1])panel(b,name+'_lens_'+side,0.13*s,0.13*s,0.012*s,0.008*s,[0,0.18*s,side*0.095*s],m.glowCool);return b;}
function mergeParts(parent){
  // Static surfaces can batch inside each semantic assembly without flattening its nodes.
  for(const c of [...parent.children])if(!(c instanceof THREE.Mesh))mergeParts(c);
  const buckets=new Map();
  for(const c of parent.children)if(c instanceof THREE.Mesh && !Array.isArray(c.material)){const key=c.material.uuid;if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(c);}
  for(const meshes of buckets.values()){if(meshes.length<2)continue;const positions=[],normals=[],colors=[];let hasColors=false;
    for(const mesh of meshes){mesh.updateMatrix();let g=mesh.geometry.clone();g.applyMatrix4(mesh.matrix);if(g.index)g=g.toNonIndexed();const p=g.getAttribute('position'),n=g.getAttribute('normal'),co=g.getAttribute('color');hasColors=hasColors||!!co;for(let i=0;i<p.count;i++){positions.push(p.getX(i),p.getY(i),p.getZ(i));normals.push(n.getX(i),n.getY(i),n.getZ(i));if(co)colors.push(co.getX(i),co.getY(i),co.getZ(i));else colors.push(1,1,1);}g.dispose();}
    const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(normals,3));if(hasColors)g.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));
    const combined=new THREE.Mesh(g,meshes[0].material);combined.name=parent.name+'_'+meshes[0].material.name.replace(/[^a-zA-Z0-9_-]/g,'_');parent.add(combined);for(const mesh of meshes)parent.remove(mesh);
  }
}
function rockGeometry(w,h,d,seed=1,n=7){
 const points=[],g=geometryBuilder(),rnd=i=>{const t=Math.sin(seed*17.17+i*43.31)*143758.5453;return t-Math.floor(t);};
 for(let k=0;k<3;k++)for(let i=0;i<n;i++){
  const a=(i/n+(k===2?0.055:0.008))*Math.PI*2+(rnd(i+7*k)-0.5)*0.18;
  const rad=(k===0?0.72:k===1?1:0.58)*(0.85+rnd(i*3+k)*0.26);
  points.push([Math.cos(a)*w*0.5*rad+(k===2?0.055*w:0),k===0?0:k===1?h*(0.32+rnd(i+50)*0.28):h*(0.70+rnd(i+80)*0.27),Math.sin(a)*d*0.5*rad]);
 }
 points.push([w*0.04,h,d*0.025]);
 // Convex faces from the authored irregular points; coplanar bottom receives one fan.
 for(let a=0;a<points.length-2;a++)for(let b=a+1;b<points.length-1;b++)for(let c=b+1;c<points.length;c++){
  if(points[a][1]===0&&points[b][1]===0&&points[c][1]===0)continue;
  const A=new THREE.Vector3(...points[a]),B=new THREE.Vector3(...points[b]),C=new THREE.Vector3(...points[c]);
  const normal=B.clone().sub(A).cross(C.clone().sub(A));if(normal.lengthSq()<1e-12)continue;
  let pos=false,neg=false;
  for(let i=0;i<points.length;i++){if(i===a||i===b||i===c)continue;const distance=normal.dot(new THREE.Vector3(...points[i]).sub(A));if(distance>1e-8)pos=true;if(distance<-1e-8)neg=true;if(pos&&neg)break;}
  if(pos&&neg)continue;if(pos)g.tri(points[a],points[c],points[b]);else g.tri(points[a],points[b],points[c]);
 }
 for(let i=1;i<n-1;i++)g.tri(points[0],points[i],points[i+1]);
 return tintStone(g.finish(),seed);
}
function stoneMaterial(m){const mat=m.rock.clone();mat.color.setRGB(1,1,1);mat.vertexColors=true;return mat;}
function erodedMesa(w,h,d,seed,n=28){
  const ys=[0,0.12,0.15,0.32,0.36,0.57,0.61,0.79,0.83,0.97,1],rs=[1,0.94,0.82,0.77,0.69,0.65,0.58,0.55,0.46,0.43,0.36],loops=[],g=geometryBuilder();
  for(let k=0;k<ys.length;k++){const row=[];for(let i=0;i<n;i++){const a=i/n*Math.PI*2,warp=1+0.07*Math.sin(i*2.7+seed)+0.045*Math.sin(i*5.2+seed*3),flute=(k%2?0.02:-0.025)*Math.sin(i*4.7+seed);row.push([Math.cos(a)*w/2*(rs[k]+flute)*warp,ys[k]*h*(1+0.015*Math.sin(i*2.1+seed)),Math.sin(a)*d/2*(rs[k]+flute)*warp]);}loops.push(row);}
  for(let k=0;k<loops.length-1;k++)for(let i=0;i<n;i++){const j=(i+1)%n;g.quad(loops[k][i],loops[k+1][i],loops[k+1][j],loops[k][j]);}
  for(let i=0;i<n;i++){const j=(i+1)%n;g.tri([0,h,0],loops.at(-1)[j],loops.at(-1)[i]);g.tri([0,0,0],loops[0][i],loops[0][j]);}
  return tintStone(g.finish(),seed);
}
function tintStone(geo,seed){const normal=geo.getAttribute('normal'),colors=[];for(let i=0;i<normal.count;i+=3){const y=normal.getY(i),c=new THREE.Color(PALETTE['regolith-mid']);if(y>0)c.lerp(new THREE.Color(PALETTE['regolith-light']),0.12+0.32*y);else c.lerp(new THREE.Color(PALETTE['shadow-plum']),0.08);c.multiplyScalar(0.97+0.04*Math.sin(i*0.71+seed));for(let j=0;j<3;j++)colors.push(c.r,c.g,c.b);}geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));return geo;}

const meta={name:'mesa-cliff-overhang',reference:'phase-2/mesa-cliff-overhang.png'};

function shelfStone(w,h,d,seed){
 const N=10,outline=Array.from({length:N},(_,i)=>{const a=i/N*Math.PI*2;return [Math.cos(a)*w/2,Math.sin(a)*d/2];}),g=geometryBuilder(),loops=[];
 const irregular=i=>Math.sin(seed*1.71+i*2.39);
 for(const [k,scale] of [[0,0.96],[1,1],[2,0.97],[3,0.94]]){
  loops.push(outline.map((p,i)=>{
   const shape=1+0.085*irregular(i),shift=(k/3-0.5)*0.045;
   return [p[0]*scale*shape+w*shift*irregular(i+2),[0,h*0.09,h*0.91,h][k]+(k===3?h*0.025*irregular(i+5):0),p[1]*scale*(1+0.08*irregular(i+4))+d*shift*irregular(i+7)];
  }));
 }
 for(let k=0;k<3;k++)for(let i=0;i<N;i++){const j=(i+1)%N;g.quad(loops[k][i],loops[k+1][i],loops[k+1][j],loops[k][j]);}
 for(let i=0;i<N;i++){const j=(i+1)%N;g.tri([0,h,0],loops[3][j],loops[3][i]);g.tri([0,0,0],loops[0][i],loops[0][j]);}
 return tintStone(g.finish(),seed);
}
async function build(){
 const root=createRoot('mesa-cliff-overhang'),m=styleMaterials(),mat=stoneMaterial(m),body=group(root,'Compact reference overhang',[0,0,0],[0,90,0]);
 const shelf=(name,w,h,d,pos,seed)=>part(body,name,shelfStone(w,h,d,seed),mat,pos);
 shelf('Chipped apron',12,0.25,5.3,[0,0,0.15],21);
 shelf('Broad shelter terrace',10.6,0.36,4.4,[0,0.24,0.05],17);
 // Closed back mass ends behind the occupant space, leaving a genuinely recessed alcove.
 shelf('Recessed fractured back wall',8.15,3.95,1.85,[0,0.5,-1.43],31);
 for(const side of [-1,1]){
  const s=side<0?'Left':'Right';
  shelf(s+' inner basal slab',2.40,1.08,2.35,[side*3.32,0.58,0.10],11+side);
  shelf(s+' inner middle slab',2.20,1.05,2.30,[side*3.29,1.60,0.06],21+side);
  shelf(s+' inner arch shoulder',2.48,1.03,2.30,[side*3.08,2.59,-0.02],31+side);
  shelf(s+' lower outer buttress',2.15,1.18,2.85,[side*4.50,0.26,-0.15],41+side);
  shelf(s+' middle outer buttress',1.87,1.12,2.55,[side*4.16,1.36,-0.22],51+side);
  shelf(s+' high outer buttress',1.66,1.05,2.45,[side*3.82,2.39,-0.30],61+side);
 }
 // Thick continuous lintel and two low, flat-topped eroded shelves reproduce the reference.
 shelf('Overhanging broad lintel',8.50,0.83,3.20,[0,3.50,-0.28],71);
 shelf('Upper stepped shelf',8.26,0.68,3.40,[0,4.26,-0.50],81);
 shelf('Flat chipped crown',6.80,0.56,2.95,[0,4.90,-0.56],91);
 // A few block joints break the rim without a regular diagonal grid.
 // Broad fractured lintel, without repeated decorative bumps.
 const zone=group(body,'shelter_zone',[0,0.615,0.33]);zone.userData={role:'shelter_trigger',boxSize:[3.7,2.8,1.7],shieldingLocation:'overhang'};
 part(zone,'Shelter floor',tintStone(plate(oct(4.4,2.25,0.38),0.05,0.007),11),mat,[0,0,0],[-90,0,0]);
 part(body,'Sample pedestal foot',rockGeometry(1.08,0.62,0.85,23,7),mat,[1.25,0.6,0.45]);
 part(body,'Sample outcrop slab',shelfStone(1.65,0.25,1.08,7),mat,[1.25,1.18,0.45]);
 for(let i=0;i<14;i++){
  const side=i%2?-1:1,x=side*(2.9+(i%5)*0.52),z=1.55+0.35*Math.sin(i*2.3);
  part(body,'Scattered apron fragment '+i,rockGeometry(0.22+i%4*0.14,0.15+i%3*0.12,0.28+i%3*0.15,101+i),mat,[x,0.25,z]);
 }
 defineBudget({triangles:12000},root);return root;
}
